import { ReactNode, FC } from 'react';

interface EmptyProps {
    /** 图片地址 */
    image?: string;
    /** 内置图片类型 */
    imageType?: 'default' | 'error' | 'network' | 'search';
    /** 图片尺寸 (rpx) */
    imageSize?: number;
    /** 描述文字 */
    description?: ReactNode;
    /** 操作区 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const Empty: FC<EmptyProps>;

export { Empty, Empty as default };
export type { EmptyProps };
